pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Initializable} from "@openzeppelin/contracts/proxy/utils/Initializable.sol";

/// @notice Configuración global que el vault lee de la factory.
interface ISplitConfig {
    function treasury() external view returns (address);
    function feeBps() external view returns (uint16);
}

/// @title SplitVault
/// @notice Dirección payTo de un vendedor. Recibe pagos x402 (USDC) y los reparte
///         entre la tesorería de Sekisho (fee) y el vendedor.
contract SplitVault is Initializable {
    using SafeERC20 for IERC20;

    uint256 public constant BPS_DENOMINATOR = 10_000;

    address public factory;
    address public merchant;

    event Distributed(
        address indexed token,
        uint256 total,
        uint256 fee,
        uint256 merchantAmount
    );

    error ZeroAddress();
    error NothingToDistribute();

    /// @dev Bloquea la implementación base; solo los clones se inicializan.
    constructor() {
        _disableInitializers();
    }

    /// @notice Se llama una sola vez, desde la factory, al crear el clon.
    function initialize(address factory_, address merchant_) external initializer {
        if (factory_ == address(0) || merchant_ == address(0)) revert ZeroAddress();
        factory = factory_;
        merchant = merchant_;
    }

    /// @notice Muestra cuánto se repartiría si se llama distribute(token) ahora.
    function pending(address token)
        external
        view
        returns (uint256 total, uint256 fee, uint256 merchantAmount)
    {
        total = IERC20(token).balanceOf(address(this));
        (fee, merchantAmount) = _split(total);
    }

    /// @notice Reparte todo el saldo de `token`. Cualquiera puede llamarla:
    ///         los destinos (tesorería y vendedor) son fijos.
    function distribute(address token)
        external
        returns (uint256 fee, uint256 merchantAmount)
    {
        uint256 total = IERC20(token).balanceOf(address(this));
        if (total == 0) revert NothingToDistribute();

        (fee, merchantAmount) = _split(total);

        if (fee > 0) {
            IERC20(token).safeTransfer(ISplitConfig(factory).treasury(), fee);
        }
        IERC20(token).safeTransfer(merchant, merchantAmount);

        emit Distributed(token, total, fee, merchantAmount);
    }

    /// @dev El redondeo favorece al vendedor (el fee redondea hacia abajo).
    function _split(uint256 total)
        internal
        view
        returns (uint256 fee, uint256 merchantAmount)
    {
        fee = (total * ISplitConfig(factory).feeBps()) / BPS_DENOMINATOR;
        merchantAmount = total - fee;
    }
}","keccak256":"0x7a6d980b276b06f7200cf8d3154e9c19cd990edb550472927cb64efb58aec702","license":"MIT"},"contracts/SplitVaultFactory.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Clones} from "@openzeppelin/contracts/proxy/Clones.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {SplitVault} from "./SplitVault.sol";

/// @title SplitVaultFactory
/// @notice Crea un SplitVault (clon EIP-1167) por vendedor y define
///         la tesorería y el fee de la plataforma.
contract SplitVaultFactory is Ownable {
    /// @notice Tope de fee: 10%. No se puede superar ni siendo owner.
    uint16 public constant MAX_FEE_BPS = 1_000;

    address public immutable implementation;
    address public treasury;
    uint16 public feeBps;

    /// @notice vendedor => su vault
    mapping(address => address) public vaultOf;

    event VaultCreated(address indexed merchant, address indexed vault);
    event TreasuryUpdated(address indexed treasury);
    event FeeUpdated(uint16 feeBps);

    error ZeroAddress();
    error FeeTooHigh();
    error VaultExists();

    constructor(address initialOwner, address treasury_, uint16 feeBps_)
        Ownable(initialOwner)
    {
        if (treasury_ == address(0)) revert ZeroAddress();
        if (feeBps_ > MAX_FEE_BPS) revert FeeTooHigh();

        implementation = address(new SplitVault());
        treasury = treasury_;
        feeBps = feeBps_;
    }

    /// @notice Crea el vault de `merchant`. Es permissionless: el dinero
    ///         solo puede ir al propio vendedor y a la tesorería.
    function createVault(address merchant) external returns (address vault) {
        if (merchant == address(0)) revert ZeroAddress();
        if (vaultOf[merchant] != address(0)) revert VaultExists();

        vault = Clones.cloneDeterministic(implementation, _salt(merchant));
        SplitVault(vault).initialize(address(this), merchant);
        vaultOf[merchant] = vault;

        emit VaultCreated(merchant, vault);
    }

    /// @notice Dirección del vault de `merchant`, exista o no todavía.
    ///         Sirve como payTo de x402 desde el primer momento.
    function predictVault(address merchant) external view returns (address) {
        return Clones.predictDeterministicAddress(implementation, _salt(merchant));
    }

    function setTreasury(address treasury_) external onlyOwner {
        if (treasury_ == address(0)) revert ZeroAddress();
        treasury = treasury_;
        emit TreasuryUpdated(treasury_);
    }

    function setFeeBps(uint16 feeBps_) external onlyOwner {
        if (feeBps_ > MAX_FEE_BPS) revert FeeTooHigh();
        feeBps = feeBps_;
        emit FeeUpdated(feeBps_);
    }

    function _salt(address merchant) internal pure returns (bytes32) {
        return bytes32(uint256(uint160(merchant)));
    }
}","keccak256":"0x5bb6eb8ed354631fe6446d425a9579314bf7dfaf569770fb9c13b78c5152c598","license":"MIT"}},"version":1}
